    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except OSError as exc:
        raise StatementError(f"cannot read {path}: {exc}") from exc
    try:
        return raw.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return raw.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise StatementError(f"cannot decode {path}: {exc}") from exc


def _is_blank(row: list[str]) -> bool:
    return all(not cell.strip() for cell in row)


def _header_columns(row: list[str]) -> dict[str, int]:
    cols: dict[str, int] = {}
    for i, cell in enumerate(row):
        cols.setdefault(cell.strip().casefold(), i)
    return cols


def _open_reader(text: str, fmt: str | None):
    """Находит заголовок. Возвращает (формат, колонки, reader, номер строки заголовка)."""
    if fmt is not None and fmt not in _FORMATS:
        raise UnknownFormatError(f"unknown format {fmt!r}")
    candidates = [fmt] if fmt is not None else list(_FORMATS)
    # первая непустая строка — заголовок; первую непустую запись ищем
    # с разделителем-запятой/точкой с запятой по очереди, номер строки физический
    for name in candidates:
        delimiter, required = _FORMATS[name]
        reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
        prev = 0
        try:
            for row in reader:
                line_no = prev + 1
                prev = reader.line_num
                if _is_blank(row):
                    continue
                cols = _header_columns(row)
                if all(c in cols for c in required):
                    return name, cols, reader, line_no
