    for row in csv.reader(io.StringIO(text, newline="")):
        if not _is_blank(row):
            header_line = 1
            break
    raise UnknownFormatError(
        "unrecognized statement header" if fmt is None else f"header does not match format {fmt!r}",
        line_no=header_line,
    )


