            if not _NOVA_DATE.fullmatch(d):
                raise ValueError
            date = dt.date.fromisoformat(d)
        except ValueError:
            raise ValueError(f"invalid date {raw_date!r}") from None
        try:
            amount = parse_amount(amount_text)
        except ValidationError as exc:
            raise ValueError(str(exc)) from exc
        return date, amount, description
    if fmt == "sfera":
        date = _sfera_date(_cell(row, cols, "дата"))
        amount = _sfera_amount(_cell(row, cols, "сумма"), signed=True)
        return date, amount, _cell(row, cols, "описание")
    date = _sfera_date(_cell(row, cols, "дата"))
    description = _cell(row, cols, "описание")
    income_text = _cell(row, cols, "приход")
    expense_text = _cell(row, cols, "расход")
    income = _sfera_amount(income_text, signed=False) if income_text.strip() else Decimal(0)
    expense = _sfera_amount(expense_text, signed=False) if expense_text.strip() else Decimal(0)
    if income and expense:
        raise ValueError("both income and expense are filled")
    if not income and not expense:
        raise ValueError("neither income nor expense is filled")
    return date, income if income else -expense, description


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store: определяет формат, пропускает дубли, копит ошибки строк."""
    text, encoding = _read_text(path)
    fmt, cols, reader, header_line = _open_reader(text, fmt)
    clock = clock or SystemClock()
    imported_at = clock.now()

    existing = Counter(
        (tx.date, tx.amount, normalize_description(tx.description)) for tx in store.all()
    )
    new_txs: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0

    def fail(line_no: int, message: str) -> None:
        if strict:
            raise StatementRowError(message, line_no=line_no)
        errors.append(RowError(line_no, message))

    prev = reader.line_num
    while True:
        line_no = prev + 1
        try:
            row = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            prev = reader.line_num
            fail(line_no, f"malformed row: {exc}")
            continue
        prev = reader.line_num
        if _is_blank(row):
            continue
        try:
            date, amount, description = _parse_fields(fmt, row, cols)
            tx = Transaction(
                date=date,
                amount=amount,
                description=description.strip(),
                imported_at=imported_at,
            )
        except (ValueError, ValidationError) as exc:
            fail(line_no, str(exc))
            continue
        key = (tx.date, tx.amount, normalize_description(tx.description))
        if existing[key] > 0:
            existing[key] -= 1
            duplicates += 1
            continue
        if categorizer is not None:
            category = categorizer.categorize(tx)
            if category is not None:
                tx = Transaction(
                    date=tx.date,
                    amount=tx.amount,
                    description=tx.description,
                    category=category,
                    imported_at=tx.imported_at,
                )
        new_txs.append(tx)

    if new_txs:
        store.add_many(new_txs)
    logger.info(
        "imported %d transactions from %s (%d duplicates, %d errors)",
        len(new_txs), path, duplicates, len(errors),
    )
    return ImportResult(fmt, encoding, len(new_txs), duplicates, errors)


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Строгий импорт выписки «Новы»; возвращает число добавленных транзакций."""
    result = import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    )
    return result.added
